// UNIT TEST - No Spring context
@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository repository;

    @InjectMocks
    private OrderService service;

    @Test
    void shouldApplyDiscountForLargeOrders() {
        var order = new Order(1L, "Laptop", 1500.0);
        when(repository.save(any())).thenReturn(order);

        var result = service.processOrder(order); // Direct method call

        assertEquals(1350.0, result.getFinalPrice()); // 10% discount applied
    }
}

// INTEGRATION TEST - Full Spring context
@SpringBootTest
class OrderIntegrationTest {
    @Autowired
    private OrderService service; // Real Spring bean

    @Autowired
    private OrderRepository repository; // Real JPA repository

    @Test
    void shouldPersistOrderToDatabase() {
        var order = new Order(null, "Monitor", 800.0);

        var saved = service.processOrder(order); // Tests entire flow

        assertNotNull(saved.getId()); // Database generated ID
        assertTrue(repository.existsById(saved.getId())); // Real DB query
    }
}

