// INTEGRATION TEST - Context startup adds 3-5 seconds
@SpringBootTest // Triggers full context initialization
@AutoConfigureTestDatabase
class PaymentIntegrationTest {
    @Autowired private PaymentService service;
    @Autowired private PaymentRepository repository;

    @Test
    void shouldPersistPaymentWithAuditLog() {
        // Spring context already started (3s overhead)
        var payment = new Payment(100.0);
        service.processPayment(payment); // Hits database

        var saved = repository.findById(payment.getId());
        assertTrue(saved.isPresent()); // Real database query
    }
}

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class) // No Spring context
class UserServiceTest {
    @Mock
    private UserRepository userRepository; // Mock dependency

    @InjectMocks
    private UserService userService; // Class under test

    @Test
    void shouldReturnUserWhenFound() {
        var user = new User(1L, "alice@example.com");
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));

        var result = userService.getUserById(1L); // Direct method call

        assertTrue(result.isPresent());
        assertEquals("alice@example.com", result.get().getEmail());
        verify(userRepository).findById(1L); // Verify interaction
    }
}

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest // Loads full application context
@AutoConfigureTestDatabase // Embedded test database
class UserIntegrationTest {
    @Autowired
    private UserService userService; // Real Spring bean

    @Autowired
    private UserRepository userRepository; // Real JPA repository

    @Test
    void shouldSaveAndRetrieveUser() {
        var user = new User(null, "bob@example.com");

        var saved = userService.createUser(user); // Calls real service & repo

        assertNotNull(saved.getId()); // Database generated ID
        var retrieved = userRepository.findById(saved.getId());
        assertTrue(retrieved.isPresent());
        assertEquals("bob@example.com", retrieved.get().getEmail());
    }
}

