// MIDDLE LAYER: Slice test - moderate speed (~20%)
@WebMvcTest(OrderController.class) // Only loads web layer
class OrderControllerTest {
    @Autowired private MockMvc mockMvc;
    @MockBean private OrderService service; // Mock service layer

    @Test
    void shouldReturnOrderJson() throws Exception {
        var order = new Order(1L, "Mouse", 50.0);
