// TOP LAYER: Full integration test - slowest, fewest tests (~10%)
@SpringBootTest(webEnvironment = RANDOM_PORT)
class OrderEndToEndTest {
    @Autowired private TestRestTemplate restTemplate;
    @Autowired private OrderRepository repository;

    @Test
    void shouldCreateOrderEndToEnd() {
        var order = new Order(null, "Monitor", 300.0);
        var response = restTemplate.postForEntity("/orders", order, Order.class);
        assertEquals(HttpStatus.CREATED, response.getStatusCode());
        assertTrue(repository.existsById(response.getBody().getId()));
    }
}

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
class InventoryServiceTest {
    @Mock
    private ProductRepository productRepository;

    @Mock
    private NotificationService notificationService;

    @InjectMocks
    private InventoryService inventoryService;

    @Test
    void shouldReorderWhenStockBelowThreshold() {
        var product = new Product(1L, "Laptop", 3); // Only 3 in stock
        when(productRepository.findById(1L)).thenReturn(Optional.of(product));

        inventoryService.checkAndReorder(1L); // Business logic under test

        // Verify reorder was triggered (threshold is 5)
        verify(notificationService).sendReorderAlert(product);
    }

    @Test
    void shouldNotReorderWhenStockSufficient() {
        var product = new Product(2L, "Mouse", 10); // Plenty in stock
        when(productRepository.findById(2L)).thenReturn(Optional.of(product));

        inventoryService.checkAndReorder(2L);

        verify(notificationService, never()).sendReorderAlert(any()); // No alert sent
    }
}

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@WebMvcTest(ProductController.class) // Only loads web layer
class ProductControllerTest {
    @Autowired
    private MockMvc mockMvc; // Spring provides this for HTTP testing

    @MockBean // Mock service layer since it's not loaded
    private ProductService productService;

    @Test
    void shouldReturnProductJson() throws Exception {
        var product = new Product(1L, "Tablet", 299.99);
        when(productService.getProduct(1L)).thenReturn(product);

        mockMvc.perform(get("/products/1")) // Simulates HTTP GET
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.name").value("Tablet"))
               .andExpect(jsonPath("$.price").value(299.99));

        verify(productService).getProduct(1L); // Verify service was called
    }
}

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import static org.junit.jupiter.api.Assertions.*;

@DataJpaTest // Loads JPA infrastructure + embedded database
class ProductRepositoryTest {
    @Autowired
    private ProductRepository repository;

    @Test
    void shouldFindProductsByPriceRange() {
        // TestEntityManager can be used for setup if needed
        repository.save(new Product(null, "Keyboard", 49.99));
        repository.save(new Product(null, "Mouse", 19.99));
        repository.save(new Product(null, "Monitor", 299.99));

        var results = repository.findByPriceBetween(20.0, 100.0);

        assertEquals(1, results.size()); // Only Keyboard in range
        assertEquals("Keyboard", results.get(0).getName());
    }

    @Test
    void shouldDeleteProductById() {
        var product = repository.save(new Product(null, "Headset", 79.99));
        repository.deleteById(product.getId());

        assertFalse(repository.existsById(product.getId())); // Verify deletion
    }
}

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest // Triggers full context startup
class ApplicationContextTest {
    @Autowired
    private ApplicationContext context; // The full Spring context

    @Autowired
    private OrderService orderService; // Real bean from context

    @Autowired
    private OrderRepository orderRepository; // Real repository

    @Test
    void contextLoadsAllBeans() {
        // Verify Spring loaded all expected beans
        assertNotNull(orderService);
        assertNotNull(orderRepository);
        assertTrue(context.containsBean("orderService"));
        assertTrue(context.containsBean("orderRepository"));

        // DataSource is auto-configured if JPA dependency present
        assertTrue(context.containsBean("dataSource"));
    }

    @Test
    void canCallRealServiceAndRepository() {
        var order = new Order(null, "Laptop", 1200.0);

        var saved = orderService.createOrder(order); // Real service call

        assertNotNull(saved.getId()); // Database generated ID
        var found = orderRepository.findById(saved.getId());
        assertTrue(found.isPresent()); // Real database query worked
    }
}

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

// CORRECT: Unit test with no Spring involvement
@ExtendWith(MockitoExtension.class) // JUnit 5 Mockito extension
class ShippingServiceTest {
    @Mock
    private WarehouseRepository warehouseRepository;

    @Mock
    private NotificationService notificationService;

    @InjectMocks
    private ShippingService shippingService; // Mockito creates instance

    @Test
    void shouldCalculateShippingCostCorrectly() {
        var warehouse = new Warehouse("NYC", 10.0);
        when(warehouseRepository.findNearest("10001")).thenReturn(warehouse);

        var cost = shippingService.calculateShipping("10001", 5.0);

        assertEquals(60.0, cost); // 10 base + 5kg * 10 per kg
        verify(warehouseRepository).findNearest("10001");
        verifyNoInteractions(notificationService); // Not called in this flow
    }
}

